package com._8x8.herd.device_logs.upload.policy;

/**
 * Why an upload is refused: one reason per check in {@link UploadPolicy}, then what can go wrong once the body is read,
 * in {@code upload.UploadFlow}. Each reason has its status code in {@code web.RejectionStatusMapper} and its response
 * in openapi.yaml, so adding one means updating both, and the parameterized web test.
 */
public enum Rejection {

    /** The path after /logs/ is not an accepted file name. 400. */
    BAD_FILE_NAME,

    /** The file type is turned off in device-logs.file-types, as calls.xml is by default. 403. */
    FILE_TYPE_DISABLED,

    /** The ALB headers do not establish who is calling. 403. */
    UNTRUSTED_IDENTITY,

    /** The certificate MAC differs from the MAC in the file name. 403. */
    MAC_MISMATCH,

    /** The request has no Content-Length, for example because it is chunked. 411. */
    LENGTH_REQUIRED,

    /** Content-Length is above the type's max-size. 413. */
    TOO_LARGE,

    /**
     * The connection ended before Content-Length bytes arrived. Tomcat answers 400 itself when its read of the body
     * fails, so this records the same code.
     */
    BODY_INCOMPLETE,

    /** The body stopped arriving for longer than Tomcat's connection timeout. Tomcat answers 408 itself, as above. */
    BODY_TIMEOUT,

    /** An object already has this key, so the create-only write was refused and nothing was overwritten. 429. */
    KEY_EXISTS,

    /** The write to storage failed or ran past its deadline. The file may still have been stored. 429, never 503. */
    STORAGE_FAILED
}
